import selfies as sf
from rdkit import Chem
from rdkit.Chem import Descriptors, rdMolDescriptors
s='''[C][C][Branch1][C][C][C][C][C@H1][Branch1][C][O][C@H1][Branch1][#Branch2][C][C][C][C][C][C][C][Ring1][=Branch1][N][C][=Branch1][C][=O][C@@H1][Branch1][C][N][C][C][=C][NH1][C][=N][Ring1][Branch1].[O][=C][Branch1][C][O][C@H1][Branch1][#Branch2][C][C][=C][C][=C][C][=C][Ring1][=Branch1][N][C][=Branch1][C][=O][N][C][C][O][C][C][Ring1][=Branch1].[C][C][N][Branch1][Ring1][C][C][C][C].[C][N][Branch1][C][C][C][=O].[N-1][=N+1][=N][P][=Branch1][C][=O][Branch1][=Branch2][C][=C][C][=C][C][=C][Ring1][=Branch1][C][=C][C][=C][C][=C][Ring1][=Branch1]'''
for i,x in enumerate(s.split('.')):
    try:
        sm=sf.decoder(x)
        m=Chem.MolFromSmiles(sm)
        print(i, sm)
        if m: print('formula',rdMolDescriptors.CalcMolFormula(m),'mw',round(Descriptors.MolWt(m),2),'rings',rdMolDescriptors.CalcNumRings(m))
    except Exception as e: print(i,'ERR',e)
